import time
from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, computed in
    parallel with a thread pool. The result is in input order, regardless
    of the number of workers or the order in which tasks finish."""
    with ThreadPoolExecutor() as ex:
        return list(ex.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4, 5]) == [0, 1, 0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([8]) == [0]


def test_parities_negative() -> None:
    assert parities([-1, -2, -3, -4]) == [1, 0, 1, 0]


def test_parities_large_matches_sequential() -> None:
    xs = [(i * 7919) % 1000 - 500 for i in range(5000)]
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


def test_parities_order_independent_of_completion_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Earlier elements take longer, so they finish last.
    def slow_parity(x: int) -> int:
        time.sleep(0.002 * max(0, 20 - x))
        return x % 2

    monkeypatch.setattr(f"{__name__}.parity", slow_parity)
    xs = list(range(20))
    assert parities(xs) == [x % 2 for x in xs]

